from pathlib import Path
import json,csv,re
import yaml
ROOT=Path('/home/jake/Developer/study');META=json.loads(Path('/tmp/ingest-six/meta.json').read_text());lib={}
for r in csv.DictReader((ROOT/'MA/Mathematical-Foundations/catalog.csv').open()):lib[int(r['topic-id'])]=(r['topic-name'],ROOT/r['lesson-path'])
for course in ['MVC','DEQ','LAL']:
 base=ROOT/'MA/Mathematical-Analysis-&-Modeling'/course
 for r in csv.DictReader((base/'topics.csv').open()):lib.setdefault(int(r['topic-id']),(r['topic-name'],base/r['lesson-path']))
def L(n):
 name,p=lib[n];assert p.is_file();assert re.search(r'^lesson-id:\s*'+str(n)+r'\s*$',p.read_text(),re.M)
 return f'[{name}](<{p.resolve().as_uri()}>)'
def image(course,code,name,alt='Source diagram'):
 return f'![{alt}](../source/{course}/{code}/{name})'
def blank(key,value,kind='math'):return {'key':key,'type':'blank','correct':{'type':kind,'value':str(value)}}
def free(value):return {'key':'response','type':'free','correct':{'type':'text','value':value}}
def Q(id,content,fields,feedback,topics,pre=(),gap=None,coverage=None):
 assert len(topics)==len(coverage)if coverage is not None else True
 return {'quiz':{'id':id,'content':content,'fields':fields,'feedback':feedback},'topics':topics,'pre':pre,'gap':gap,'coverage':coverage}
def F(id,prompt,reference,feedback,topics,pre=(),**kw):return Q(id,prompt,[free(reference)],feedback,topics,pre,**kw)
def B(id,prompt,value,feedback,topics,pre=(),key='answer',kind='math',**kw):return Q(id,prompt,[blank(key,value,kind)],feedback,topics,pre,**kw)
DATA=[]
def A(idx,instructions,problems,extra=''):DATA.append((META[idx-1],instructions,problems,extra))
def problem(n,source,blocks,context=''):return {'number':n,'source':source,'blocks':blocks,'context':context}
