expressions=[(r'\nabla\phi','vector field',[1934],'The gradient takes a scalar function to a vector field.'),(r'\nabla\cdot\phi','undefined',[2131],'Divergence requires a vector input; the supplied input is scalar.'),(r'\nabla\times\phi','undefined',[2132],'Curl requires a vector field, not a scalar function.'),(r'\nabla\mathbf F','undefined',[1934],'Under the scalar-gradient convention, a vector is not an admissible gradient input.'),(r'\nabla\cdot\mathbf F','scalar function',[2131],'Divergence sums component derivatives and produces a scalar function.'),(r'\nabla\times\mathbf F','vector field',[2132],'The three-dimensional curl produces a vector field.'),(r'\nabla\cdot(\nabla\phi)','scalar function',[1934,2131],'The inner gradient is a vector field, whose divergence is scalar.'),(r'\nabla\times(\nabla\phi)','vector field',[1934,2132],'The curl takes the inner vector field to a vector field. If the mixed partials are continuous it is the zero vector field; zero does not change its type.'),(r'\nabla(\nabla\cdot\mathbf F)','vector field',[2131,1934],'The inner divergence is scalar, so its gradient is a vector field.'),(r'\nabla\cdot(\nabla\cdot\mathbf F)','undefined',[2131],'The inner divergence is scalar, so it cannot be the input to another divergence.'),(r'\nabla\times(\nabla\cdot\mathbf F)','undefined',[2131,2132],'The inner divergence is scalar, but curl needs a vector field.'),(r'\nabla(\nabla\times\mathbf F)','undefined',[2132,1934],'The inner curl is a vector field; its tensor gradient is not the scalar-gradient operation used here.'),(r'\nabla\cdot(\nabla\times\mathbf F)','scalar function',[2132,2131],'The curl is a vector field, so its divergence is scalar. When the mixed partials are continuous this scalar is zero.'),(r'\nabla\times(\nabla\times\mathbf F)','vector field',[2132],'Both curl operations accept and produce vector fields in three dimensions.')]
