 if extra:note+='\n'+extra+'\n'
 note+='\nStudy answers, explanations, and graphics labeled “Authored reference” are additions, not publisher-provided solutions.\n\n## Topics\n\n'+'\n'.join('- '+L(t)for t in sorted(topics))+'\n\n## Prerequisites\n\n'+('\n'.join('- '+L(t)for t in sorted(pre))if pre else 'No additional prerequisite links needed.')+'\n\n## Instructions\n\n'+instructions+'\n\n'
 qs=[]
 for p in problems:
  note+='---\n\n## Problem '+str(p['number'])+'\n\nSource question: '+p['source']+'\n\n'
  if p['context']:note+=p['context']+'\n\n'
