   quiz=q['quiz']
   # Convert explicit paragraph markers used in compact raw strings to real paragraphs.
   quiz['content']=quiz['content'].replace(r'\n\n','\n\n')
   note+='```quiz\n'+yaml.safe_dump(quiz,sort_keys=False,allow_unicode=True,width=110)+'```\n\n'
   if q['gap']:
    note+='**Topics:** No whole-task equivalent verified for '+q['gap']+'. Component coverage: '+'; '.join(L(t)+' ('+c+')'for t,c in zip(q['topics'],q['coverage']))+'.\n'
   else:note+='**Topics:** '+'; '.join(L(t)for t in q['topics'])+'.\n'
